    export default {
        props: {
            id: {
                type: String,
                default: '',
            },
            value: {
                type: Boolean,
                default: false,
            },
            label: {
                type: String,
                default: '',
            },
            isChild: {
                type: Boolean,
                default: false,
            },
        },

        computed: {
            checkboxValue: {
                get() {
                    return this.value;
                },

                set(val) {
                    this.$emit('input', val);
                },
            },
        },
    };
